async function ingestArtifact(kind: string, week: string, filePath: string) {
  const existing = await db.query(
    'SELECT id FROM cr_artifacts WHERE kind=$1 AND week=$2', [kind, week]);
  if (existing.rows.length > 0) {
    log.info(`artifact ${kind}/${week} already present, skipping`);
    return existing.rows[0].id;
  }
  const bytes = await fs.readFile(filePath);
  const sha = sha256(bytes);
  return insertArtifact(kind, week, bytes, sha);
}
